/*
 * kmem.c - Windows kernel driver: maps a user buffer and services
 *          read/write requests for a caller-chosen virtual address range.
 *
 * Build (kernel):
 *   Use a standard WDK build environment. Add this file to your Sources/
 *   CMakeLists and link against ntoskrnl.lib + BufferOverflowK.lib.
 *
 * Smoke-test build (user-mode stub, MSVC):
 *   cl /DSMOKE_TEST kmem.c /link /subsystem:console
 */

#ifndef SMOKE_TEST
#include <ntddk.h>
#include <wdm.h>
#else
/* Minimal stubs so the file compiles as a user-mode smoke test. */
#include <windows.h>
#include <stdio.h>
typedef LONG NTSTATUS;
typedef ULONG_PTR KAFFINITY;
#define NT_SUCCESS(s)        ((NTSTATUS)(s) >= 0)
#define STATUS_SUCCESS       ((NTSTATUS)0x00000000L)
#define STATUS_INVALID_PARAMETER ((NTSTATUS)0xC000000DL)
#define STATUS_ACCESS_VIOLATION  ((NTSTATUS)0xC0000005L)
#define STATUS_BUFFER_TOO_SMALL  ((NTSTATUS)0xC0000023L)
#define STATUS_UNSUCCESSFUL  ((NTSTATUS)0xC0000001L)
#define STATUS_NOT_SUPPORTED ((NTSTATUS)0xC00000BBL)
#define STATUS_PENDING       ((NTSTATUS)0x00000103L)
#define METHOD_BUFFERED       0
#define FILE_READ_DATA        0x0001
#define FILE_WRITE_DATA       0x0002
typedef struct _IO_STATUS_BLOCK { NTSTATUS Status; ULONG_PTR Information; } IO_STATUS_BLOCK, *PIO_STATUS_BLOCK;
typedef struct _UNICODE_STRING { USHORT Length; USHORT MaximumLength; PWSTR Buffer; } UNICODE_STRING, *PUNICODE_STRING;
typedef void *PDEVICE_OBJECT;
typedef void *PDRIVER_OBJECT;
typedef void *PIRP;
typedef void *PIO_STACK_LOCATION;
typedef void DRIVER_UNLOAD;
typedef void DRIVER_DISPATCH;
#define DbgPrint printf
#define ExAllocatePoolWithTag(t,s,g) malloc(s)
#define ExFreePoolWithTag(p,g)       free(p)
#define IoCompleteRequest(i,b)
#define IoGetCurrentIrpStackLocation(i) NULL
#define MmProbeAndLockPages(m,a,o)
#define MmUnlockPages(m)
#define MmGetSystemAddressForMdlSafe(m,p) NULL
#define IoAllocateMdl(a,l,s,c,i) NULL
#define IoFreeMdl(m)
#define IoCreateDevice(d,e,n,t,c,ex,o) STATUS_SUCCESS
#define IoCreateSymbolicLink(s,d)      STATUS_SUCCESS
#define IoDeleteDevice(d)
#define IoDeleteSymbolicLink(s)
#define RtlInitUnicodeString(d,s)
typedef UCHAR KIRQL;
#define PASSIVE_LEVEL 0
typedef void* MDL;
typedef void* PMDL;
#define NonPagedPool 0
#define KernelMode   0
#define UserMode     1
#define IoReadAccess  0
#define IoWriteAccess 1
#define IO_NO_INCREMENT 0
#define DO_BUFFERED_IO  0x4
#define FILE_DEVICE_UNKNOWN 0x22
typedef struct _DRIVER_OBJECT { void *MajorFunction[28]; void *DriverUnload; } DRIVER_OBJECT_STUB;
#endif /* SMOKE_TEST */

/* -------------------------------------------------------------------------
 * IOCTL codes
 * ------------------------------------------------------------------------- */
#define KMEM_DEVICE_TYPE    FILE_DEVICE_UNKNOWN
#define KMEM_IOCTL_READ     CTL_CODE(KMEM_DEVICE_TYPE, 0x900, METHOD_BUFFERED, FILE_READ_DATA)
#define KMEM_IOCTL_WRITE    CTL_CODE(KMEM_DEVICE_TYPE, 0x901, METHOD_BUFFERED, FILE_WRITE_DATA)

#ifndef CTL_CODE
#define CTL_CODE(DevType, Function, Method, Access) \
    (((DevType) << 16) | ((Access) << 14) | ((Function) << 2) | (Method))
#endif

/* -------------------------------------------------------------------------
 * Request structures passed in the IOCTL input buffer
 * ------------------------------------------------------------------------- */
#pragma pack(push, 1)
typedef struct _KMEM_REQUEST {
    ULONG_PTR TargetAddress;   /* virtual address in the caller's process     */
    SIZE_T    Length;           /* byte count to read or write                 */
    /* For KMEM_IOCTL_WRITE: the data to write immediately follows this header
     * in the same input buffer (InputBuffer[sizeof(KMEM_REQUEST)..]).
     * For KMEM_IOCTL_READ:  output is written to OutputBuffer.               */
} KMEM_REQUEST, *PKMEM_REQUEST;
#pragma pack(pop)

/* -------------------------------------------------------------------------
 * Device / symbolic-link names
 * ------------------------------------------------------------------------- */
#define DEVICE_NAME_W   L"\\Device\\KMem"
#define SYMLINK_NAME_W  L"\\DosDevices\\KMem"

/* -------------------------------------------------------------------------
 * Forward declarations
 * ------------------------------------------------------------------------- */
#ifndef SMOKE_TEST
DRIVER_UNLOAD   KMemUnload;
DRIVER_DISPATCH KMemCreate;
DRIVER_DISPATCH KMemClose;
DRIVER_DISPATCH KMemDeviceControl;

static NTSTATUS
KMemReadWrite(
    _In_    PEPROCESS   Process,
    _In_    ULONG_PTR   TargetAddress,
    _Inout_ PVOID       Buffer,
    _In_    SIZE_T      Length,
    _In_    BOOLEAN     bWrite);
#endif

/* -------------------------------------------------------------------------
 * Safe memory copy via MDL (kernel → user and user → kernel paths)
 *
 * Locks the target pages at the given virtual address (interpreted in the
 * context of the supplied PEPROCESS), creates an MDL, maps it into system
 * space, performs the copy, then cleans up.
 * ------------------------------------------------------------------------- */
#ifndef SMOKE_TEST
static NTSTATUS
KMemCopyViaAttach(
    _In_    PEPROCESS   TargetProcess,
    _In_    ULONG_PTR   TargetVA,
    _Inout_ PVOID       KernelBuffer,
    _In_    SIZE_T      Length,
    _In_    BOOLEAN     bWrite)
{
    NTSTATUS    status   = STATUS_SUCCESS;
    PMDL        pMdl     = NULL;
    PVOID       pMapped  = NULL;
    KAPC_STATE  apcState = { 0 };

    if (Length == 0 || KernelBuffer == NULL || TargetVA == 0)
        return STATUS_INVALID_PARAMETER;

    /* Attach to the target process address space. */
    KeStackAttachProcess(TargetProcess, &apcState);

    __try {
        pMdl = IoAllocateMdl(
            (PVOID)TargetVA,
            (ULONG)Length,
            FALSE,
            FALSE,
            NULL);

        if (pMdl == NULL) {
            status = STATUS_UNSUCCESSFUL;
            __leave;
        }

        /* Probe + lock; raises on bad address. */
        MmProbeAndLockPages(
            pMdl,
            UserMode,
            bWrite ? IoWriteAccess : IoReadAccess);

        pMapped = MmGetSystemAddressForMdlSafe(pMdl, NormalPagePriority);
        if (pMapped == NULL) {
            MmUnlockPages(pMdl);
            IoFreeMdl(pMdl);
            pMdl   = NULL;
            status = STATUS_ACCESS_VIOLATION;
            __leave;
        }

        if (bWrite)
            RtlCopyMemory(pMapped, KernelBuffer, Length);  /* kernel buf → target */
        else
            RtlCopyMemory(KernelBuffer, pMapped, Length);  /* target → kernel buf */

        MmUnlockPages(pMdl);
        IoFreeMdl(pMdl);
        pMdl = NULL;
    }
    __except (EXCEPTION_EXECUTE_HANDLER) {
        status = GetExceptionCode();
        if (pMdl != NULL) {
            IoFreeMdl(pMdl);
            pMdl = NULL;
        }
    }

    KeUnstackDetachProcess(&apcState);
    return status;
}

/* -------------------------------------------------------------------------
 * IRP_MJ_CREATE / IRP_MJ_CLOSE — trivial accept
 * ------------------------------------------------------------------------- */
NTSTATUS
KMemCreate(
    _In_ PDEVICE_OBJECT DeviceObject,
    _In_ PIRP           Irp)
{
    UNREFERENCED_PARAMETER(DeviceObject);
    Irp->IoStatus.Status      = STATUS_SUCCESS;
    Irp->IoStatus.Information = 0;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return STATUS_SUCCESS;
}

NTSTATUS
KMemClose(
    _In_ PDEVICE_OBJECT DeviceObject,
    _In_ PIRP           Irp)
{
    UNREFERENCED_PARAMETER(DeviceObject);
    Irp->IoStatus.Status      = STATUS_SUCCESS;
    Irp->IoStatus.Information = 0;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return STATUS_SUCCESS;
}

/* -------------------------------------------------------------------------
 * IRP_MJ_DEVICE_CONTROL — dispatch KMEM_IOCTL_READ / KMEM_IOCTL_WRITE
 * ------------------------------------------------------------------------- */
NTSTATUS
KMemDeviceControl(
    _In_ PDEVICE_OBJECT DeviceObject,
    _In_ PIRP           Irp)
{
    UNREFERENCED_PARAMETER(DeviceObject);

    PIO_STACK_LOCATION  stack       = IoGetCurrentIrpStackLocation(Irp);
    NTSTATUS            status      = STATUS_SUCCESS;
    ULONG_PTR           information = 0;

    ULONG  ioCode    = stack->Parameters.DeviceIoControl.IoControlCode;
    ULONG  inLen     = stack->Parameters.DeviceIoControl.InputBufferLength;
    ULONG  outLen    = stack->Parameters.DeviceIoControl.OutputBufferLength;
    PVOID  sysBuffer = Irp->AssociatedIrp.SystemBuffer;   /* METHOD_BUFFERED */

    /* Both IOCTLs require at least the fixed header in the input buffer. */
    if (sysBuffer == NULL || inLen < sizeof(KMEM_REQUEST)) {
        status = STATUS_BUFFER_TOO_SMALL;
        goto Complete;
    }

    PKMEM_REQUEST req = (PKMEM_REQUEST)sysBuffer;

    if (req->Length == 0 || req->TargetAddress == 0) {
        status = STATUS_INVALID_PARAMETER;
        goto Complete;
    }

    /* Look up the calling process (the one that issued the IOCTL). */
    PEPROCESS callerProcess = IoGetRequestorProcess(Irp);
    if (callerProcess == NULL) {
        status = STATUS_UNSUCCESSFUL;
        goto Complete;
    }

    switch (ioCode) {

    /* ---- READ: copy from caller virtual range → output buffer ---------- */
    case KMEM_IOCTL_READ: {
        if (outLen < (ULONG)req->Length) {
            status = STATUS_BUFFER_TOO_SMALL;
            break;
        }

        /*
         * For METHOD_BUFFERED the I/O manager allocates one contiguous system
         * buffer of max(inLen, outLen) bytes.  The output portion starts at
         * offset 0 of that same buffer.  We use a separate scratch allocation
         * so we don't alias the header we just read.
         */
        PVOID scratch = ExAllocatePoolWithTag(
            NonPagedPool,
            req->Length,
            'meRK');

        if (scratch == NULL) {
            status = STATUS_UNSUCCESSFUL;
            break;
        }

        status = KMemCopyViaAttach(
            callerProcess,
            req->TargetAddress,
            scratch,
            req->Length,
            FALSE);   /* read */

        if (NT_SUCCESS(status)) {
            RtlCopyMemory(sysBuffer, scratch, req->Length);
            information = req->Length;
        }

        ExFreePoolWithTag(scratch, 'meRK');
        break;
    }

    /* ---- WRITE: copy from input buffer → caller virtual range ---------- */
    case KMEM_IOCTL_WRITE: {
        SIZE_T requiredIn = sizeof(KMEM_REQUEST) + req->Length;
        if (inLen < (ULONG)requiredIn) {
            status = STATUS_BUFFER_TOO_SMALL;
            break;
        }

        PVOID writeData = (PUCHAR)sysBuffer + sizeof(KMEM_REQUEST);

        status = KMemCopyViaAttach(
            callerProcess,
            req->TargetAddress,
            writeData,
            req->Length,
            TRUE);    /* write */

        if (NT_SUCCESS(status))
            information = req->Length;

        break;
    }

    default:
        status = STATUS_NOT_SUPPORTED;
        break;
    }

Complete:
    Irp->IoStatus.Status      = status;
    Irp->IoStatus.Information = information;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return status;
}

/* -------------------------------------------------------------------------
 * Driver unload
 * ------------------------------------------------------------------------- */
VOID
KMemUnload(
    _In_ PDRIVER_OBJECT DriverObject)
{
    UNICODE_STRING symLink;
    RtlInitUnicodeString(&symLink, SYMLINK_NAME_W);
    IoDeleteSymbolicLink(&symLink);
    IoDeleteDevice(DriverObject->DeviceObject);
    DbgPrint("KMem: unloaded\n");
}

/* -------------------------------------------------------------------------
 * DriverEntry
 * ------------------------------------------------------------------------- */
NTSTATUS
DriverEntry(
    _In_ PDRIVER_OBJECT  DriverObject,
    _In_ PUNICODE_STRING RegistryPath)
{
    UNREFERENCED_PARAMETER(RegistryPath);

    NTSTATUS       status;
    PDEVICE_OBJECT deviceObject = NULL;
    UNICODE_STRING devName, symLink;

    RtlInitUnicodeString(&devName,  DEVICE_NAME_W);
    RtlInitUnicodeString(&symLink, SYMLINK_NAME_W);

    status = IoCreateDevice(
        DriverObject,
        0,
        &devName,
        KMEM_DEVICE_TYPE,
        0,
        FALSE,
        &deviceObject);

    if (!NT_SUCCESS(status)) {
        DbgPrint("KMem: IoCreateDevice failed: 0x%08X\n", status);
        return status;
    }

    deviceObject->Flags |= DO_BUFFERED_IO;

    status = IoCreateSymbolicLink(&symLink, &devName);
    if (!NT_SUCCESS(status)) {
        DbgPrint("KMem: IoCreateSymbolicLink failed: 0x%08X\n", status);
        IoDeleteDevice(deviceObject);
        return status;
    }

    DriverObject->MajorFunction[IRP_MJ_CREATE]         = KMemCreate;
    DriverObject->MajorFunction[IRP_MJ_CLOSE]          = KMemClose;
    DriverObject->MajorFunction[IRP_MJ_DEVICE_CONTROL] = KMemDeviceControl;
    DriverObject->DriverUnload                         = KMemUnload;

    DbgPrint("KMem: loaded — device %wZ  symlink %wZ\n", &devName, &symLink);
    return STATUS_SUCCESS;
}

#endif /* !SMOKE_TEST */

/* =========================================================================
 * Smoke-test entry point (user-mode build only)
 * Exercises structure layout and IOCTL code generation; no actual I/O.
 * ========================================================================= */
#ifdef SMOKE_TEST
int main(void)
{
    printf("sizeof(KMEM_REQUEST) = %zu\n", sizeof(KMEM_REQUEST));
    printf("KMEM_IOCTL_READ  = 0x%08X\n",
        CTL_CODE(FILE_DEVICE_UNKNOWN, 0x900, METHOD_BUFFERED, FILE_READ_DATA));
    printf("KMEM_IOCTL_WRITE = 0x%08X\n",
        CTL_CODE(FILE_DEVICE_UNKNOWN, 0x901, METHOD_BUFFERED, FILE_WRITE_DATA));

    /* Verify the header is exactly what a client would pack. */
    KMEM_REQUEST r = { 0 };
    r.TargetAddress = (ULONG_PTR)0xDEADBEEFDEADBEEFULL;
    r.Length        = 128;
    printf("Test request: addr=0x%llX len=%zu\n",
        (unsigned long long)r.TargetAddress, (size_t)r.Length);

    printf("Smoke test passed.\n");
    return 0;
}
#endif /* SMOKE_TEST */
